const viewer = (window.viewer = new Cesium.Viewer('cesiumContainer', {
  baseLayer: new Cesium.ImageryLayer(new Cesium.OpenStreetMapImageryProvider({
    url: 'https://tile.openstreetmap.org/',
    maximumLevel: 18,
    credit: 'OpenStreetMap contributors',
  })),
  baseLayerPicker: false,
  navigationHelpButton: false,
  animation: false,
  timeline: false,
  geocoder: false,
  homeButton: false,
  sceneModePicker: false,
  fullscreenButton: false,
  infoBox: false,
  selectionIndicator: false,
}));

viewer.scene.globe.enableLighting = false;

// Clock range covering several days around 2024-07-01
const startTime = Cesium.JulianDate.fromIso8601('2024-06-28T00:00:00Z');
const stopTime  = Cesium.JulianDate.fromIso8601('2024-07-06T00:00:00Z');

viewer.clock.startTime   = startTime.clone();
viewer.clock.stopTime    = stopTime.clone();
viewer.clock.currentTime = Cesium.JulianDate.fromIso8601('2024-07-01T00:00:00Z');
viewer.clock.clockRange  = Cesium.ClockRange.LOOP_STOP;
viewer.clock.multiplier  = 86400; // advance one day per real second

// TimeIntervalCollection: one interval per day; dataCallback supplies {Time}
const times = Cesium.TimeIntervalCollection.fromIso8601({
  iso8601: '2024-06-28/2024-07-06/P1D',
  dataCallback: (interval) => ({
    Time: Cesium.JulianDate.toIso8601(interval.start, 0).substring(0, 10),
  }),
});

// MODIS Terra TrueColor via NASA GIBS WMTS (epsg3857 / Web Mercator)
const modisProvider = new Cesium.WebMapTileServiceImageryProvider({
  url: 'https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/' +
       'MODIS_Terra_CorrectedReflectance_TrueColor/default/{Time}/' +
       'GoogleMapsCompatible_Level9/{TileMatrix}/{TileRow}/{TileCol}.jpeg',
  layer: 'MODIS_Terra_CorrectedReflectance_TrueColor',
  style: 'default',
  tileMatrixSetID: 'GoogleMapsCompatible_Level9',
  format: 'image/jpeg',
  maximumLevel: 9,
  clock: viewer.clock,
  times: times,
  credit: new Cesium.Credit('NASA Global Imagery Browse Services (GIBS)'),
});

const modisLayer = new Cesium.ImageryLayer(modisProvider, {
  alpha: 1.0,
});
viewer.imageryLayers.add(modisLayer);

// Frame on Greenland / North Atlantic
viewer.camera.setView({
  destination: Cesium.Cartesian3.fromDegrees(-42.0, 68.0, 7500000),
  orientation: {
    heading: 0.0,
    pitch: Cesium.Math.toRadians(-90),
    roll: 0.0,
  },
});
